const payload = $input.first()?.json || {};
const legacyRaw = payload.linkHinhAnh || payload.content?.linkHinhAnh || '';
const legacyUrls = String(legacyRaw).split(/[,\n]+/).map((url) => url.trim()).filter(Boolean);
const media = Array.isArray(payload.media) && payload.media.length ? payload.media : legacyUrls.map((url) => ({ url }));
const uniqueMedia = [...new Map(media.filter((item) => item?.url).map((item) => [item.url, item])).values()];
if (!uniqueMedia.length) return [{ json: { ...payload, image_url: '', image_index: -1, image_count: 0, images: [] } }];
return uniqueMedia.map((image, index) => ({ json: { ...payload, image_url: image.url, image_index: index, image_count: uniqueMedia.length, images: uniqueMedia } }));

// Mode: Run Once for Each Item
// Input: mỗi item đến từ "Parse Image URLs", đã có sẵn image_url, image_index, image_count

let imageUrl = $json.image_url;

// Clean the URL
imageUrl = imageUrl.trim();

// Convert common sharing links to direct download links
// Google Drive
if (imageUrl.includes('drive.google.com/file/d/')) {
  const fileIdMatch = imageUrl.match(/\/d\/([^\/]+)/);
  if (fileIdMatch) {
    imageUrl = `https://drive.google.com/uc?export=download&id=${fileIdMatch[1]}`;
  }
}

// Dropbox - change dl=0 to dl=1
if (imageUrl.includes('dropbox.com') && imageUrl.includes('dl=0')) {
  imageUrl = imageUrl.replace('dl=0', 'dl=1');
}

// Imgur - convert to direct image link
if (imageUrl.includes('imgur.com/') && !imageUrl.includes('i.imgur.com')) {
  imageUrl = imageUrl.replace('imgur.com/', 'i.imgur.com/') + '.jpg';
}

// OneDrive/SharePoint
if (imageUrl.includes('sharepoint.com') || imageUrl.includes('1drv.ms')) {
  imageUrl = imageUrl.split('?')[0] + '?download=1';
}

return {
  json: {
    original_url: $json.image_url,
    direct_download_url: imageUrl,
    image_index: $json.image_index,
    image_count: $json.image_count
  }
};

const body = $json.body || $json;
if (!body.postId) throw new Error('Missing postId');
if (!body.scheduledAt) throw new Error('Missing scheduledAt');
const platform = String(body.platform || '').trim().toLowerCase();
if (!['facebook', 'linkedin', 'youtube', 'tiktok'].includes(platform)) throw new Error('Unsupported platform');
const postType = String(body.postType || 'post').trim().toLowerCase();
const content = String(body.content || body.description || body.title || '').trim();
if (!content) throw new Error('Missing content');
const scheduledAt = new Date(body.scheduledAt);
if (Number.isNaN(scheduledAt.getTime())) throw new Error('Invalid scheduledAt');

const cleanUrl = (value) => {
  let url = String(value || '').trim();
  const markdownMatch = url.match(/^\[(.*?)\]\((.*?)\)$/);
  if (markdownMatch) url = markdownMatch[2];
  url = url.replace(/\\&/g, '&').replace(/&amp;/g, '&').trim();
  const driveMatch = url.match(/drive\.google\.com\/file\/d\/([A-Za-z0-9_-]+)/) || url.match(/[?&]id=([A-Za-z0-9_-]+)/);
  if (driveMatch && url.includes('drive.google.com')) {
    url = 'https://drive.google.com/uc?export=download&confirm=t&id=' + driveMatch[1];
  }
  return url;
};

const rawMedia = Array.isArray(body.media) ? body.media : (Array.isArray(body.mediaUrls) ? body.mediaUrls : []);
const media = rawMedia.map((item) => {
  const source = typeof item === 'string' ? { url: item } : (item || {});
  return { ...source, url: cleanUrl(source.url || source.originalUrl || source.videoUrl) };
}).filter((item) => item.url);

return { json: { postId: String(body.postId), scheduledAt: scheduledAt.toISOString(), platform, postType, content, tiktokOptions: body.tiktokOptions || null, title: String(body.title || '').trim(), description: String(body.description || '').trim(), employee: String(body.employee || ''), note: String(body.note || ''), media, mediaUrls: media.map((item) => item.url) } };

const payload = $('Chuẩn hóa dữ liệu publish').first().json;
const media = Array.isArray(payload.media) ? payload.media : [];
const video = media.find((item) => String(item?.mimeType || '').startsWith('video/')) || media.find((item) => item?.videoUrl || /video/i.test(String(item?.fileName || '')));
if (!video?.url) throw new Error('Missing YouTube video URL');
return { json: { ...payload, video_url: video.url, youtube_title: String(payload.title || 'EPCB Video').slice(0, 100), youtube_description: payload.description || payload.content } };

const payload = $json;
const cleanUrl = (value) => {
  let url = String(value || '').trim();
  const markdownMatch = url.match(/^\[(.*?)\]\((.*?)\)$/);
  if (markdownMatch) url = markdownMatch[2];
  const driveMatch = url.match(new RegExp('(?:/d/|[?&]id=)([A-Za-z0-9_-]+)'));
  if (driveMatch && url.includes('drive.google.com')) url = 'https://drive.google.com/uc?export=download&confirm=t&id=' + driveMatch[1];
  return url.replace(/\\&/g, '&').replace(/&amp;/g, '&').trim();
};
const rawMedia = Array.isArray(payload.media) ? payload.media : (Array.isArray(payload.mediaUrls) ? payload.mediaUrls : []);
const media = rawMedia.map((item) => {
  const source = typeof item === 'string' ? { url: item } : (item || {});
  return { ...source, url: cleanUrl(source.url || source.originalUrl || source.videoUrl) };
}).filter((item) => item.url);
return [{ json: { ...payload, media, mediaUrls: media.map((item) => item.url) } }];

const payload = $('Chuẩn hóa dữ liệu publish').first().json;
const media = Array.isArray(payload.media) ? payload.media : [];
const video = media.find((item) => String(item?.mimeType || '').startsWith('video/')) || media.find((item) => item?.videoUrl || /video/i.test(String(item?.fileName || '')));
if (!video?.url) throw new Error('Missing Facebook Reel video URL');
return { json: { ...payload, video_url: video.url, reel_title: String(payload.title || '').slice(0, 100), reel_description: payload.description || payload.content } };

const source = $binary?.data;
if (!source) throw new Error('Facebook Reel upload requires binary data field data');
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
if (!buffer?.length) throw new Error('Facebook Reel video binary is empty');
const binary = await this.helpers.prepareBinaryData(buffer, source.fileName || 'facebook-reel.mp4', source.mimeType || 'video/mp4');
return { json: { ...$json, reel_file_size: buffer.length }, binary: { data: binary } };

const payload = $json;
if (payload.postType !== 'tiktok_video') throw new Error('TikTok chỉ hỗ trợ tiktok_video.');
const media = (payload.media || []).filter(m => String(m.mimeType || '').startsWith('video/') || /\.(mp4|mov|webm)(?:[?#]|$)/i.test(m.fileName || m.url || ''));
if (media.length !== 1 || !media[0].url) throw new Error('TikTok cần đúng một video.');
if (!payload.content?.trim() || payload.content.length > 2200) throw new Error('Caption TikTok cần từ 1 đến 2200 ký tự.');
const options = payload.tiktokOptions;
if (!options?.privacyLevel) throw new Error('Chưa chọn quyền riêng tư TikTok.');
if (options.brandContent && options.privacyLevel === 'SELF_ONLY') throw new Error('Branded content không hỗ trợ SELF_ONLY.');
return [{json: {...payload, video_url: media[0].url}}];

if ($json.error?.code !== 'ok') throw new Error('TikTok creator: ' + ($json.error?.code || 'invalid_response'));
const payload = $('Prepare TikTok Video').first().json;
const creator = $json.data;
if (!creator?.privacy_level_options?.includes(payload.tiktokOptions.privacyLevel)) throw new Error('Quyền riêng tư không được tài khoản TikTok hỗ trợ.');
return [{json: {...payload, creator}}];

const item = $input.first();
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const mime = item.binary?.data?.mimeType || '';
if (/html|json|text/i.test(mime) || /^\s*(?:<!doctype|<html)/i.test(buffer.subarray(0, 100).toString())) throw new Error('Link video trả về trang HTML; kiểm tra quyền tải file Drive.');
// Detect the container instead of trusting Drive's generic application/octet-stream.
const signature = buffer.subarray(0, 16);
const videoMime = signature.subarray(4, 8).toString() === 'ftyp' ? (signature.subarray(8, 12).toString() === 'qt  ' ? 'video/quicktime' : 'video/mp4') : signature.subarray(0, 4).toString('hex') === '1a45dfa3' ? 'video/webm' : '';
if (!videoMime) throw new Error('Video phải là MP4, MOV hoặc WebM.');
const size = buffer.length;
if (!size || size > 4 * 1024 ** 3) throw new Error('Video TikTok phải lớn hơn 0 và không quá 4 GB.');
const chunkSize = Math.min(size, 32 * 1024 ** 2);
return [{json: {...$('Validate TikTok Creator').first().json, video_size: size, chunk_size: chunkSize, total_chunk_count: Math.max(1, Math.floor(size / chunkSize)), video_mime: videoMime}, binary: item.binary}];

if ($json.error?.code !== 'ok' || !$json.data?.publish_id || !$json.data?.upload_url) throw new Error('TikTok init: ' + ($json.error?.code || 'invalid_response'));
const uploadUrl = $json.data.upload_url;
if (!/^https:\/\/[^/]+\.tiktokapis\.com\//i.test(uploadUrl)) throw new Error('Invalid TikTok upload host');
return [{json: {...$('Measure TikTok Video').first().json, publish_id: $json.data.publish_id, upload_url: uploadUrl}, binary: $('Measure TikTok Video').first().binary}];

const session = $json;
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const chunks = [];
for (let index = 0; index < session.total_chunk_count; index++) {
  const start = index * session.chunk_size;
  const end = index === session.total_chunk_count - 1 ? session.video_size : start + session.chunk_size;
  const binary = await this.helpers.prepareBinaryData(buffer.subarray(start, end), 'tiktok-chunk', session.video_mime);
  chunks.push({json: {upload_url: session.upload_url, content_range: `bytes ${start}-${end - 1}/${session.video_size}`, chunk_length: end - start, video_mime: session.video_mime}, binary: {data: binary}});
}
return chunks;

const previous = $('Wait TikTok Processing').first(0, $runIndex).json;
if ($json.error?.code !== 'ok') throw new Error('TikTok status: ' + ($json.error?.code || 'invalid_response') + '. Kiểm tra publish_id ' + previous.publish_id + ' trước khi đăng lại.');
const state = $json.data?.status;
if (state === 'FAILED') throw new Error('TikTok: ' + ($json.data.fail_reason || 'publish_failed'));
const pollCount = previous.pollCount + 1;
if (state !== 'PUBLISH_COMPLETE' && pollCount >= 120) throw new Error('Chưa xác nhận kết quả TikTok sau 60 phút; publish_id=' + previous.publish_id + '. Kiểm tra trạng thái trước khi đăng lại để tránh trùng video.');
return [{json: {publish_id: previous.publish_id, pollCount, complete: state === 'PUBLISH_COMPLETE', externalPostId: String($json.data?.publicaly_available_post_id?.[0] || previous.publish_id), response: $json}}];
